        IsBigEndian = isBigEndian;
    }

    enum DecodeResult
    {
        Success = 0,
        InvalidInput,
        OutputOverflow,
    }

    /// <summary>
    /// Gets Douglas Crockford's Base32 flavor with substitution characters.
    /// </summary>
    public static Base32 Crockford => crockford.Value;

    /// <summary>
    /// Gets RFC 4648 variant of Base32 coder.
    /// </summary>
