        bytesWritten = 0;
        int o = 0;
        for (int i = 0; i < input.Length; i++)
        {
            char c = input[i];
            int b = table[c] - 1;
            if (b < 0)
            {
                bytesWritten = o;
                return DecodeResult.InvalidInput;
            }

            if (bitsLeft > bitsPerChar)
            {
                bitsLeft -= bitsPerChar;
                outputPad |= b << bitsLeft;
                continue;
            }

