            outputPad |= b >> shiftBits;
            if (o >= output.Length)
            {
                return DecodeResult.OutputOverflow;
            }

            output[o++] = (byte)outputPad;
            b &= (1 << shiftBits) - 1;
            bitsLeft = bitsPerByte - shiftBits;
            outputPad = b << bitsLeft;
        }

        bytesWritten = o;
        return DecodeResult.Success;
    }
